}
.funder-party-chart svg {
  display: block;
  width: 100%;
}
.funder-party-chart svg g {
  cursor: pointer;
}
.funder-party-chart svg g:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
.funder-party-legend {
  list-style: none;
  padding: 0;
  margin: 0;
}
.funder-party-legend:has(> li:nth-child(3)) {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  column-gap: 16px;
}
.funder-party-legend li {
  border-bottom: 1px solid var(--line);
}
.funder-party-legend button {
  display: grid;
  grid-template-columns: 12px minmax(0, 1fr);
  gap: 12px;
  align-items: center;
  width: 100%;
  padding: 10px 0;
  text-align: left;
  border: 0;
  background: transparent;
  color: inherit;
  font: inherit;
  cursor: pointer;
}
.party-swatch {
  width: 10px;
  height: 10px;
  border-radius: 50%;
}
.party-tooltip {
  position: fixed;
  z-index: 10;
  max-width: min(280px, calc(100vw - 24px));
  padding: 12px 16px;
  background: var(--surface);
  color: var(--text);
  border: 1px solid var(--line);
  box-shadow: 0 4px 16px #0002;
  overflow-wrap: anywhere;
}
.party-tooltip span,
.party-tooltip strong {
  display: block;
}
.party-tooltip strong {
  margin-top: 4px;
  font-variant-numeric: tabular-nums;
}
.funder-recipients {
  display: block;
  margin-bottom: 40px;
}
.funder-recipients table {
  width: 100%;
}
.funder-recorded-names {
  margin-top: 36px;
}
.funder-recorded-names summary {
  cursor: pointer;
  font-weight: 600;
}
.funder-page .declaration-heading a {
  color: inherit;
}
